source.patch:
From 6b7b9c2612dc5c8ee1f7d2604c417666e883a2e6 Mon Sep 17 00:00:00 2001
From: Allen Winter <winter@kde.org>
Date: Tue, 21 Jan 2025 15:28:09 -0500
Subject: [PATCH] Some MSAN fixes for uninitialized memory

---
 src/libical/icalrecur.c    | 7 +++----
 src/libical/icaltimezone.c | 7 ++++---
 src/libical/icaltz-util.c  | 4 ++--
 src/libical/icalvalue.c    | 2 +-
 src/libicalvcal/vobject.c  | 1 +
 5 files changed, 11 insertions(+), 10 deletions(-)

diff --git a/src/libical/icalrecur.c b/src/libical/icalrecur.c
index 1041236..009a098 100644
--- a/src/libical/icalrecur.c
+++ b/src/libical/icalrecur.c
@@ -776,12 +776,11 @@ struct icalrecurrencetype *icalrecurrencetype_clone(struct icalrecurrencetype *r

 struct icalrecurrencetype *icalrecurrencetype_new_from_string(const char *str)
 {
-    struct icalrecur_parser parser;
+    struct icalrecur_parser parser = {0};
     icalrecurrencetype_byrule byrule;

     icalerror_check_arg_re(str != 0, "str", 0);

-    memset(&parser, 0, sizeof(parser));
     parser.rt = icalrecurrencetype_new();
     if (!parser.rt) {
         return NULL;
@@ -961,7 +960,7 @@ char *icalrecurrencetype_as_string_r(struct icalrecurrencetype *recur)
     char *str;
     char *str_p;
     size_t buf_sz = 200;
-    char temp[20];
+    char temp[20] = {0};
     int i, j;

     if (recur == 0 || recur->freq == ICAL_NO_RECURRENCE) {
@@ -1632,7 +1631,7 @@ static int initialize_rscale(icalrecur_iterator *impl)
 {
     struct icalrecurrencetype *rule = impl->rule;
     struct icaltimetype dtstart = impl->dtstart;
-    char locale[ULOC_KEYWORD_AND_VALUES_CAPACITY] = "";
+    char locale[ULOC_KEYWORD_AND_VALUES_CAPACITY] = {0};
     UErrorCode status = U_ZERO_ERROR;
     UChar *tzid = (UChar *)UCAL_UNKNOWN_ZONE_ID;
     bool is_hebrew = false;
diff --git a/src/libical/icaltimezone.c b/src/libical/icaltimezone.c
index 3773648..b448643 100644
--- a/src/libical/icaltimezone.c
+++ b/src/libical/icaltimezone.c
@@ -812,7 +812,8 @@ void icaltimezone_convert_time(struct icaltimetype *tt,

 int icaltimezone_get_utc_offset(icaltimezone *zone, struct icaltimetype *tt, int *is_daylight)
 {
-    icaltimezonechange *zone_change, *prev_zone_change, tt_change, tmp_change;
+    icaltimezonechange *zone_change, *prev_zone_change;
+    icaltimezonechange tt_change = {0}, tmp_change = {0};
     size_t change_num, change_num_to_use;
     int found_change;
     int step, utc_offset_change, cmp;
@@ -1650,8 +1651,8 @@ static void icaltimezone_parse_zone_tab(void)
     const char *zonedir, *zonetab;
     char *filename;
     FILE *fp;
-    char buf[1024];      /* Used to store each line of zones.tab as it is read. */
-    char location[1024]; /* Stores the city name when parsing buf. */
+    char buf[1024] = {0};      /* Used to store each line of zones.tab as it is read. */
+    char location[1024] = {0}; /* Stores the city name when parsing buf. */
     size_t filename_len;
     int latitude_degrees = 0, latitude_minutes = 0, latitude_seconds = 0;
     int longitude_degrees = 0, longitude_minutes = 0, longitude_seconds = 0;
diff --git a/src/libical/icaltz-util.c b/src/libical/icaltz-util.c
index 5a5b7d5..09eb01a 100644
--- a/src/libical/icaltz-util.c
+++ b/src/libical/icaltz-util.c
@@ -188,7 +188,7 @@ static char *zname_from_stridx(char *str, size_t idx)

 static void set_zoneinfopath(void)
 {
-    char file_path[MAXPATHLEN];
+    char file_path[MAXPATHLEN] = {0};
     const char *fname = ZONES_TAB_SYSTEM_FILENAME;
     size_t i, num_zi_search_paths;

@@ -697,7 +697,7 @@ icalcomponent *icaltzutil_fetch_timezone(const char *location)
                 /* No rule, so ignore the TZ string */
                 tzstr = NULL;
             } else {
-                struct icaltimetype std_trans, dst_trans;
+                struct icaltimetype std_trans = {0}, dst_trans = {0};

                 /* Parse std->dst rule */
                 p = parse_posix_rule(++p, /* skip ',' */
diff --git a/src/libical/icalvalue.c b/src/libical/icalvalue.c
index 61e2527..0f04eee 100644
--- a/src/libical/icalvalue.c
+++ b/src/libical/icalvalue.c
@@ -1030,7 +1030,7 @@ void print_datetime_to_string(char *str, const struct icaltimetype *data)
 #pragma GCC diagnostic push
 #pragma GCC diagnostic ignored "-Wstringop-truncation"
 #endif
-    char temp[20];
+    char temp[20] = {0};

     str[0] = '\0';
     if (data != 0) {
diff --git a/src/libicalvcal/vobject.c b/src/libicalvcal/vobject.c
index ca37d0e..1136a21 100644
--- a/src/libicalvcal/vobject.c
+++ b/src/libicalvcal/vobject.c
@@ -101,6 +101,7 @@ char* dupStr(const char *s, size_t size)
         }
     t = (char*)malloc(size+1);
     if (t) {
+        memset(t,0,size+1);
         memcpy(t,s,size);
         t[size] = 0;
         return t;
-- 
2.43.0
